@dataclass
class Inv:
    workflows:int=0; dockerfiles:int=0; bound:int=0; hermetic:int=0; npm_ci:int=0; expo:int=0; eas:int=0

def blob_sha(p:Path)->str:
    b=p.read_bytes(); return hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()

def canon(v:Any)->Any:
    if isinstance(v,dict): return {str(k):canon(x) for k,x in sorted(v.items(),key=lambda z:str(z[0]))}
    if isinstance(v,list): return [canon(x) for x in v]
    if isinstance(v,str): return v.replace('\r\n','\n').replace('\r','\n').strip()
    return v

def wf_projection(d:dict[str,Any])->dict[str,Any]:
    out={}; jobs=d.get('jobs')
    if isinstance(jobs,dict):
        for n,j in jobs.items():
            if not isinstance(j,dict): continue
            steps=[]
            if isinstance(j.get('steps'),list):
                for s in j['steps']:
                    steps.append({k:s[k] for k in ('uses','with','run','shell','working-directory','env') if k in s} if isinstance(s,dict) else s)
            out[str(n)]={k:j[k] for k in ('env','defaults','container','services') if k in j}; out[str(n)]['steps']=steps
    return canon({'env':d.get('env'),'jobs':out})

def digest(v:Any)->str: return hashlib.sha256(json.dumps(canon(v),sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()).hexdigest()
def wf_digest(d:dict[str,Any])->str: return digest(wf_projection(d))

def docker_lines(t:str)->list[str]:
    out=[]; cur=''
    for raw in t.replace('\r\n','\n').replace('\r','\n').splitlines():
        s=raw.strip()
        if not cur and (not s or s.startswith('#')): continue
        cur=(cur+' '+s).strip() if cur else s
        if cur.endswith('\\'): cur=cur[:-1].rstrip(); continue
        out.append(re.sub(r'\s+',' ',cur)); cur=''
    if cur: out.append(re.sub(r'\s+',' ',cur))
    return out

def docker_digest(t:str)->str: return digest([x for x in docker_lines(t) if re.match(r'^(FROM|RUN)\s+',x,re.I)])

def inspect(root:Path):
    root=Path(root).resolve(); ctx=semantic_base.inspect(root); inv=Inv(); setattr(ctx,'closed_world',inv)
    yaml=semantic_base.load_yaml(ctx.errors)
    if yaml is None:return ctx
    base=root/'.github/workflows'; paths=sorted({*base.glob('*.yml'),*base.glob('*.yaml')}); actual={p.relative_to(root).as_posix():p for p in paths}
    if set(actual)!=set(WORKFLOWS): ctx.errors.append(f'closed-world workflow inventory changed; missing={sorted(set(WORKFLOWS)-set(actual))} unexpected={sorted(set(actual)-set(WORKFLOWS))}; UNKNOWN=FAIL-CLOSED')
    for rel,expected in WORKFLOWS.items():
        p=actual.get(rel)
        if not p: continue
        try:d=yaml.safe_load(p.read_text(encoding='utf-8'))
        except Exception as e:ctx.errors.append(f'{rel}: semantic parse unavailable: {e}');continue
        if not isinstance(d,dict):ctx.errors.append(f'{rel}: workflow root not mapping');continue
        if wf_digest(d)!=expected:ctx.errors.append(f'{rel}: UNPROVEN semantic execution change; UNKNOWN/AMBIGUOUS=FAIL-CLOSED')
        inv.workflows+=1
        jobs=d.get('jobs')
        if isinstance(jobs,dict):
            for j in jobs.values():
                if isinstance(j,dict) and isinstance(j.get('steps'),list):
                    for s in j['steps']:
                        if isinstance(s,dict) and isinstance(s.get('run'),str):
                            r=s['run']; inv.hermetic+=r.count('backend/hermetic_python.py'); inv.npm_ci+=r.count('npm ci'); inv.expo+=r.count('.github/npm-tools/node_modules/.bin/expo-doctor'); inv.eas+=r.count('.github/npm-tools/node_modules/.bin/eas')
    docks={p.relative_to(root).as_posix():p for p in root.rglob('Dockerfile*') if '.git' not in p.parts and p.is_file()}
    if set(docks)!=set(DOCKER):ctx.errors.append(f'closed-world Dockerfile inventory changed; missing={sorted(set(DOCKER)-set(docks))} unexpected={sorted(set(docks)-set(DOCKER))}; UNKNOWN=FAIL-CLOSED')
    for rel,expected in DOCKER.items():
        p=docks.get(rel)
        if p and docker_digest(p.read_text(encoding='utf-8'))!=expected:ctx.errors.append(f'{rel}: UNPROVEN FROM/RUN semantic change; FAIL-CLOSED')
        if p:inv.dockerfiles+=1
    for rel,expected in BOUND.items():
        try:actual_blob=blob_sha(root/rel)
        except OSError as e:ctx.errors.append(f'{rel}: reviewed helper/lock unavailable: {e}');continue
        if actual_blob!=expected:ctx.errors.append(f'{rel}: reviewed helper/lock bytes changed; helper indirection=FAIL-CLOSED')
        inv.bound+=1
    for label,count in [('hermetic Python',inv.hermetic),('npm ci',inv.npm_ci),('local Expo Doctor',inv.expo),('local EAS',inv.eas)]:
        if count<1:ctx.errors.append(f'approved positive path missing: {label}')
    return ctx

def head(root:Path)->str:
    try:return subprocess.run(['git','rev-parse','HEAD'],cwd=root,text=True,capture_output=True,check=True).stdout.strip()
    except Exception:return 'unavailable'

def print_inv(ctx,root:Path)->None:
    semantic_base.print_inventory(ctx); i:Inv=ctx.closed_world
    print(f'EXECUTABLE_TOOLING_CHECKOUT_SHA={head(root)}');print(f'EXECUTABLE_TOOLING_POLICY_MODE={POLICY_MODE}');print(f'EXECUTABLE_TOOLING_WORKFLOWS={i.workflows}');print(f'EXECUTABLE_TOOLING_DOCKERFILES={i.dockerfiles}');print(f'EXECUTABLE_TOOLING_BOUND_HELPERS_LOCKS={i.bound}');print(f'EXECUTABLE_TOOLING_HERMETIC_PYTHON_MENTIONS={i.hermetic}');print(f'EXECUTABLE_TOOLING_NPM_CI_MENTIONS={i.npm_ci}');print(f'EXECUTABLE_TOOLING_LOCAL_EXPO_DOCTOR_MENTIONS={i.expo}');print(f'EXECUTABLE_TOOLING_LOCAL_EAS_MENTIONS={i.eas}')
    print('EXECUTABLE_TOOLING_APPROVED_PYTHON=backend/hermetic_python.py/hash-locked closures');print('EXECUTABLE_TOOLING_APPROVED_NPM_CI=reviewed lock-bound current forms');print('EXECUTABLE_TOOLING_APPROVED_LOCAL_BINARIES=Expo-Doctor,EAS from .github/npm-tools/node_modules/.bin');print('EXECUTABLE_TOOLING_SHELL_INDIRECTION=no-shell-parser; any semantic run change incl -c/-lc/eval/source/dynamic=FAIL-CLOSED');print('EXECUTABLE_TOOLING_PACKAGE_EXECUTORS=any unreviewed npm-exec/npm-x/npx/pnpm/yarn/bun/corepack spelling=FAIL-CLOSED');print('EXECUTABLE_TOOLING_NPM_RUN_STRATEGY=B; no release-critical npm-run approved');print('EXECUTABLE_TOOLING_UNKNOWN_AMBIGUOUS=FAIL-CLOSED')

def main()->int:
    ap=argparse.ArgumentParser();ap.add_argument('--root',type=Path,default=Path('.'));a=ap.parse_args();root=a.root.resolve();ctx=inspect(root);print_inv(ctx,root)
    if ctx.errors:
        print('EXECUTABLE_TOOLING_PRODUCTION_POLICY=fail');[print(f'- {e}') for e in ctx.errors];return 1
    print('EXECUTABLE_TOOLING_PRODUCTION_POLICY=pass');return 0
if __name__=='__main__':raise SystemExit(main())